    referenceSnippet: `/* त्रिभुज ज्यामिति एवं समरूपता प्रमेय सूत्र */
• थेल्स प्रमेय (BPT): △ABC में यदि DE ∥ BC हो, तो AD / DB = AE / EC
• BPT का विलोम: यदि रेखा AD/DB = AE/EC करे, तो DE ∥ BC होगी।
• समरूप त्रिभुजों के परिमापों का अनुपात: परिमाप(△ABC) / परिमाप(△PQR) = AB / PQ = BC / QR = AC / PR
• पाइथागोरस प्रमेय: कर्ण² = लंब² + आधार²  (AC² = AB² + BC² यदि ∠B = 90°)
• पाइथागोरस त्रिक (Pythagorean Triplets): (3, 4, 5), (5, 12, 13), (7, 24, 25), (8, 15, 17)`,
