    referenceSnippet: `/* वृत्त एवं क्षेत्रमिति मुख्य सूत्र (Mensuration Master Blueprint) */
• त्रिज्यखंड क्षेत्रफल: A = (θ / 360°) × πr²; चाप लंबाई: l = (θ / 360°) × 2πr
• वृत्तखंड का क्षेत्रफल = त्रिज्यखंड का क्षेत्रफल - संगत त्रिभुज का क्षेत्रफल
• बेलन (Cylinder): वक्र पृष्ठ = 2πrh; कुल पृष्ठ = 2πr(r + h); आयतन = πr²h
• शंकु (Cone): तिर्यक ऊंचाई l = √(r² + h²); वक्र पृष्ठ = πrl; आयतन = ⅓πr²h
• गोला (Sphere): पृष्ठीय क्षेत्रफल = 4πr²; आयतन = ⁴⁄₃πr³
• अर्धगोला (Hemisphere): वक्र पृष्ठ = 2πr²; कुल पृष्ठ = 3πr²; आयतन = ⅔πr³`,
