    referenceSnippet: `/* सांख्यिकी एवं प्रायिकता गणितीय सूत्र (Statistics & Probability) */
• माध्यक सूत्र: Median = l + [((n/2) - cf) / f] × h
• बहुलक सूत्र: Mode = l + [(f₁ - f₀) / (2f₁ - f₀ - f₂)] × h
• केंद्रीय प्रवृत्तियों का अनुभवजन्य संबंध: 3 × माध्यक = बहुलक + 2 × माध्य
• सैद्धांतिक प्रायिकता: P(E) = n(E) / n(S)  [0 ≤ P(E) ≤ 1]
• पूरक घटना की प्रायिकता: P(Ē) = 1 - P(E)
• ताश की गड्डी (52 पत्ते): 26 लाल (13 पान, 13 ईंट) + 26 काले (13 हुकुम, 13 चिड़ी); 12 फेस कार्ड`,
