        a: 'अशोक का धम्म कोई संकीर्ण पूजा-पद्धति या कर्मकांड नहीं था, बल्कि एक सार्वभौमिक नैतिक आचार संहिता (Universal Moral Code) थी। इसके मुख्य तत्व थे: माता-पिता व गुरुजनों का आदर, सभी धर्मों और संप्रदायों का सम्मान (सर्वधर्म समभाव), दासों व सेवकों के प्रति दयालुता, अहिंसा (जीवों की हत्या पर रोक), तथा मनुष्य व पशु दोनों के लिए निःशुल्क चिकित्सालयों एवं वृक्षारोपण की व्यवस्था।'
