        a: 'प्राचीन भारतीय वंशावलियों, पुराणों और जनश्रुतियों के अनुसार भगवान राम के ज्येष्ठ पुत्र कुश से चली सूर्यवंशी शाखा कालांतर में विभिन्न क्षेत्रों में फैली। शाक्य गणराज्य (जिनमें भगवान बुद्ध हुए) और मौर्य राजवंश (चंद्रगुप्त व अशोक) इसी सूर्यवंशी क्षत्रिय परंपरा की शाखाएं मानी जाती हैं। वर्तमान समय में कुशवाहा, मौर्य, शाक्य और सैनी समुदाय स्वयं को गर्व के साथ इसी गौरवशाली कुल और चक्रवर्ती सम्राटों का वंशज मानते हैं।'
