        a: 'इस ऐतिहासिक 13 न्यायाधीशों की संविधान पीठ ने फैसला दिया कि संविधान के अनुच्छेद 368 के तहत संसद की संशोधन शक्ति असीमित नहीं है। संसद संविधान के किसी भी हिस्से में संशोधन कर सकती है, लेकिन वह संविधान के मूलभूत तत्वों—जैसे लोकतंत्र, पंथनिरपेक्षता, न्यायपालिका की स्वतंत्रता, शक्तियों का पृथक्करण और मौलिक अधिकारों का सार—को समाप्त नहीं कर सकती।'
