    referenceSnippet: `/* Defensive Secure Coding: Preventing SQL Injection */
// ❌ VULNERABLE: Direct string concatenation allows attacker to inject "admin' OR '1'='1"
const query = "SELECT * FROM users WHERE email = '" + userEmail + "'";

// ✅ SECURE: Parameterized Prepared Statements separate code from user-supplied data
const secureQuery = "SELECT id, email, role FROM users WHERE email = $1 AND is_active = true";
const result = await db.query(secureQuery, [userEmail]);`,
    viva: [
      {
        q: 'How does a TCP SYN Stealth Scan (-sS) in Nmap work without establishing a full connection?',
        a: 'The scanner sends a raw TCP SYN packet to a target port. If the port responds with a SYN/ACK, the port is OPEN. The scanner immediately sends an RST (Reset) packet to tear down the socket before the 3-way handshake completes. This avoids completing the session and leaves minimal traces in application-level logs.'
      },
      {
        q: 'What is the difference between Stored Cross-Site Scripting (XSS) and Reflected XSS?',
        a: 'Stored (Persistent) XSS occurs when malicious JavaScript payload is permanently stored in the target database (e.g., in a comment field) and executed in the browser of every visitor who views that page. Reflected XSS occurs when payload in a URL query parameter is immediately reflected back in the HTTP response without being saved permanently.'
      },
      {
        q: 'What is the core architectural principle of "Zero Trust Architecture"?',
        a: '"Never trust, always verify." Unlike traditional perimeter security (which trusts everything inside the corporate firewall), Zero Trust assumes threats exist both inside and outside the network. Every request must be strictly authenticated, authorized, and encrypted based on identity, device posture, and least-privilege access.'
      }
    ],
